pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 guessHash) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 3 ether);

        vm.startPrank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);
        vm.stopPrank();

        vm.roll(block.number + 2);

        bool ok;
        vm.startPrank(actor);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        vm.deal(actor, 3 ether);
        bool secondLockSucceeded;
        vm.startPrank(actor);
        try c.lockInGuess{value: 1 ether}(guessHash) {
            secondLockSucceeded = true;
        } catch {
            secondLockSucceeded = false;
        }
        vm.stopPrank();

        assertTrue(secondLockSucceeded);
    }
}
